passes.source:
precision highp float;

uniform vec2 iResolution;
uniform vec4 iMouse;

// Bound with feedback: the state this buffer wrote last tick.
uniform sampler2D iChannel0;

uniform float u_startValue;

// The UI's memory. Every texel holds the same state:
// r = slider value, g = switch (0 or 1), b = pointer was down last tick, a = 1 once written.
void main() {
  vec4 state = texture2D(iChannel0, gl_FragCoord.xy / iResolution);
  // A buffer starts out all zeros; alpha 0 means nothing was written yet.
  if (state.a < 0.5) state = vec4(u_startValue, 0.0, 0.0, 1.0);

  bool down = iMouse.z > 0.0;
  bool wasDown = state.b > 0.5;
  vec2 pointer = toUi(iMouse.xy, iResolution);

  // Dragging along the track moves the slider.
  if (down && overSlider(pointer)) {
    state.r = clamp((pointer.x + SLIDER_HALF) / (2.0 * SLIDER_HALF), 0.0, 1.0);
  }
  // A press that starts on the switch flips it: once per press, not once per frame.
  if (down && !wasDown && overSwitch(pointer)) state.g = 1.0 - state.g;
  state.b = down ? 1.0 : 0.0;

  gl_FragColor = state;
}

precision highp float;

uniform vec2 iResolution;
uniform float iTime;
uniform vec4 iMouse;

// Buffer A: the UI state (see that pass).
uniform sampler2D iChannel0;

uniform vec3 u_accent;
uniform vec3 u_panel;
uniform float u_startValue;

// Paint the shape at distance d in ink, with an edge one pixel soft.
vec3 paint(vec3 color, float d, vec3 ink, float pixel) {
  return mix(color, ink, smoothstep(pixel, -pixel, d));
}

void main() {
  float pixel = 1.0 / iResolution.y;
  vec2 p = toUi(gl_FragCoord.xy, iResolution);
  vec2 pointer = toUi(iMouse.xy, iResolution);
  bool down = iMouse.z > 0.0;

  vec4 state = texture2D(iChannel0, vec2(0.5));
  float value = state.a > 0.5 ? state.r : u_startValue;
  float on = state.g;

  vec3 color = mix(vec3(0.05, 0.06, 0.09), vec3(0.1, 0.11, 0.16), p.y + 0.5);
  color = paint(color, sdBox(p, vec2(0.45, 0.33), 0.04), u_panel, pixel);

  // Slider: the track, the part up to the knob, and the knob, which grows under the pointer.
  vec2 start = vec2(-SLIDER_HALF, SLIDER_Y);
  vec2 knob = vec2(-SLIDER_HALF + 2.0 * SLIDER_HALF * value, SLIDER_Y);
  bool overTrack = overSlider(pointer);
  color = paint(color, sdSegment(p, start, vec2(SLIDER_HALF, SLIDER_Y)) - 0.012, vec3(0.26, 0.28, 0.34), pixel);
  color = paint(color, sdSegment(p, start, knob) - 0.012, u_accent, pixel);
  color = paint(color, length(p - knob) - (overTrack ? 0.034 : 0.028), (overTrack && down) ? u_accent : vec3(0.95), pixel);

  // Switch: a pill whose knob slides to the lit side when it is on.
  vec3 pill = mix(vec3(0.26, 0.28, 0.34), u_accent, on);
  if (overSwitch(pointer)) pill += 0.08;
  color = paint(color, sdBox(p - SWITCH_CENTER, SWITCH_HALF, SWITCH_HALF.y), pill, pixel);
  vec2 switchKnob = SWITCH_CENTER + vec2(mix(-1.0, 1.0, on) * (SWITCH_HALF.x - SWITCH_HALF.y), 0.0);
  color = paint(color, length(p - switchKnob) - (SWITCH_HALF.y - 0.008), vec3(0.97), pixel);

  // What the controls drive: the slider sets the orb's size, the switch its colour and pulse.
  float radius = 0.03 + 0.09 * value * (1.0 + 0.08 * on * sin(iTime * 4.0));
  float orb = length(p - vec2(0.22, 0.13)) - radius;
  vec3 orbColor = mix(vec3(0.55, 0.57, 0.62), u_accent, on);
  color += orbColor * 0.25 * exp(-max(orb, 0.0) * 30.0);
  color = paint(color, orb, orbColor, pixel);

  // The pointer, as a ring.
  color = paint(color, abs(length(p - pointer) - 0.012) - 0.002, vec3(1.0), pixel);

  gl_FragColor = vec4(color, 1.0);
}

// Shared by Buffer A and the Image pass, so both agree on where every control is.
// UI space: the canvas centre is (0, 0) and its height runs from -0.5 to 0.5.

const float SLIDER_Y = -0.17;
const float SLIDER_HALF = 0.32;
const vec2 SWITCH_CENTER = vec2(-0.22, 0.13);
const vec2 SWITCH_HALF = vec2(0.09, 0.045);

vec2 toUi(vec2 pixel, vec2 resolution) {
  return (pixel - 0.5 * resolution) / resolution.y;
}

float sdBox(vec2 p, vec2 halfSize, float radius) {
  vec2 q = abs(p) - halfSize + radius;
  return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - radius;
}

float sdSegment(vec2 p, vec2 a, vec2 b) {
  vec2 pa = p - a;
  vec2 ba = b - a;
  return length(pa - ba * clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0));
}

bool overSlider(vec2 p) {
  return abs(p.y - SLIDER_Y) < 0.05 && abs(p.x) < SLIDER_HALF + 0.03;
}

bool overSwitch(vec2 p) {
  return sdBox(p - SWITCH_CENTER, SWITCH_HALF, SWITCH_HALF.y) < 0.0;
}

