passes.source:
precision highp float;

uniform vec2 iResolution;
uniform float iTime;

uniform float u_count;
uniform float u_size;
uniform float u_speed;
uniform vec3 u_colorA;
uniform vec3 u_colorB;

// A stable pseudo-random number in 0..1 for every input: the particle's identity.
float hash(float n) {
  return fract(sin(n * 127.1) * 43758.5453);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution) / iResolution.y;
  vec3 color = vec3(0.015, 0.015, 0.04);

  // No state: every particle's position is a function of its index and the time.
  // GLSL ES loops need a constant bound, so the count control stops the loop early.
  for (int i = 0; i < 64; i++) {
    float id = float(i);
    if (id >= u_count) break;
    float life = 2.0 + 3.0 * hash(id);
    float age = fract((iTime * u_speed + hash(id + 7.0) * life) / life);
    vec2 start = vec2((hash(id + 1.0) - 0.5) * 1.6, -0.65);
    vec2 drift = vec2(0.15 * sin(age * 6.2831 + id), 1.3 * age);
    vec2 offset = uv - (start + drift);
    float fade = sin(age * 3.14159);
    float glow = exp(-dot(offset, offset) / (u_size * u_size));
    color += mix(u_colorA, u_colorB, hash(id + 3.0)) * glow * fade;
  }

  // Additive light can exceed 1: map it back smoothly instead of clipping.
  gl_FragColor = vec4(1.0 - exp(-color * 1.5), 1.0);
}

